def patch():
    with open(HERITAGE_FILE, "r", encoding="utf-8") as f:
        items = json.load(f)

    count = 0
    for item in items:
        name = item["name"]
        if name in SPECIFIC_DATA:
            d = SPECIFIC_DATA[name]
            for key in ['description', 'techniques', 'inheritors', 'cultural_meaning']:
                if key in d:
                    item[key] = d[key]
            count += 1
        elif name in REMAINING_ITEMS:
            d = REMAINING_ITEMS[name]
            if 'desc' in d: item['description'] = d['desc']
            if 'techs' in d: item['techniques'] = d['techs']
            if 'inheritors' in d: item['inheritors'] = d['inheritors']
            if 'meaning' in d: item['cultural_meaning'] = d['meaning']
            count += 1

    print(f"Patched {count} items with specific data")

    with open(HERITAGE_FILE, "w", encoding="utf-8") as f:
        json.dump(items, f, ensure_ascii=False, indent=2)

    # Re-seed
    from app.models.database import SessionLocal, init_db
    from app.models.exhibition import HeritageItem
    init_db()
    db = SessionLocal()
    db.query(HeritageItem).delete()
    db.commit()
    for item in items:
        db.add(HeritageItem(
            name=item["name"], category=item["category"], region=item["region"],
            era=item["era"], description=item["description"],
            techniques_json=json.dumps(item["techniques"], ensure_ascii=False),
            inheritors_json=json.dumps(item["inheritors"], ensure_ascii=False),
            images_json=json.dumps(item["images"], ensure_ascii=False),
            cultural_meaning=item["cultural_meaning"],
        ))
    db.commit()
    db.close()
    print(f"Re-seeded {len(items)} items")
    print("Done!")

if __name__ == "__main__":
    patch()
